import type { SessionThreadCreditsRecord } from '../../../core/system/session-policy-log';

/**
 * Oct-2 Phase D Step 11.1: Codex's own credit estimate for one root thread.
 *
 * The app-server's supported `account/usage/read` request takes an optional
 * `threadId` and returns `threadUsage` (verified against the 0.163.0 protocol
 * schema generated by `codex app-server generate-json-schema`):
 *   { threadId, estimatedUsageCreditsMicros, estimatedUsageUsdMicros | null,
 *     groups: [{ model, reasoningEffort, speed, inputTokens, cachedInputTokens,
 *                netNewInputTokens, outputTokens, totalTokens,
 *                estimatedUsageCreditsMicros }] }
 * `threadUsage` is null when Codex has no billing route for the thread
 * (for example an API-key login), so a missing reading is normal, not an error.
 * Nothing here handles a login token: the app-server makes its own request.
 */
export type CodexThreadCredits = Omit<SessionThreadCreditsRecord, 'event' | 'provider' | 'sessionKind' | 'arm' | 'armKey'>;

export interface CodexUsageReadClient {
  request(method: 'account/usage/read', params: { threadId: string }, timeoutMs?: number): Promise<unknown>;
}

const MAX_GROUPS = 20;
const count = (value: unknown): number | null => typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : null;
const text = (value: unknown): string | null => typeof value === 'string' && value ? value.slice(0, 100) : null;

/** Reads `threadUsage` defensively; anything unrecognised yields no reading rather than a guess. */
export function parseCodexThreadCredits(response: unknown, expectedThreadId: string): CodexThreadCredits | null {
  const usage = (response as { threadUsage?: unknown } | null | undefined)?.threadUsage;
  if (!usage || typeof usage !== 'object') return null;
  const record = usage as Record<string, unknown>;
  const credits = count(record['estimatedUsageCreditsMicros']);
  if (record['threadId'] !== expectedThreadId || credits === null) return null;
  const groups = (Array.isArray(record['groups']) ? record['groups'] : []).slice(0, MAX_GROUPS).flatMap((entry) => {
    const group = entry && typeof entry === 'object' ? entry as Record<string, unknown> : null;
    const groupCredits = count(group?.['estimatedUsageCreditsMicros']);
    return group && groupCredits !== null
      ? [{ model: text(group['model']), reasoningEffort: text(group['reasoningEffort']), speed: text(group['speed']),
        totalTokens: count(group['totalTokens']), estimatedUsageCreditsMicros: groupCredits }]
      : [];
  });
  const known = groups.map((group) => group.totalTokens).filter((tokens): tokens is number => tokens !== null);
  return {
    threadId: expectedThreadId,
    estimatedUsageCreditsMicros: credits,
    estimatedUsageUsdMicros: count(record['estimatedUsageUsdMicros']),
    totalTokens: known.length > 0 ? known.reduce((sum, tokens) => sum + tokens, 0) : null,
    groups,
  };
}

/**
 * One read, hard-bounded: the request carries the deadline and so does a timer, because the
 * answer must never hold up a shutdown or a thread replacement. Returns null for an
 * unsupported Codex version, no billing route, a dead or wedged app-server, or any failure;
 * a missing reading is reported as missing, never filled in.
 */
export async function readCodexThreadCredits(
  client: CodexUsageReadClient,
  threadId: string,
  timeoutMs = 2_500,
): Promise<CodexThreadCredits | null> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    const deadline = new Promise<never>((_, reject) => {
      timer = setTimeout(() => reject(new Error('account/usage/read timed out')), timeoutMs);
      timer.unref?.();
    });
    return parseCodexThreadCredits(await Promise.race([client.request('account/usage/read', { threadId }, timeoutMs), deadline]), threadId);
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Which root threads of one adapter may still be read. A thread is read at most once, and
 * only if it ran a turn here, so a replacement thread that never ran is not asked about and
 * the thread that was replaced and the one that replaced it can each be recorded.
 */
export class CodexThreadCreditsLedger {
  private readonly ranTurn = new Set<string>();
  private readonly attempted = new Set<string>();

  noteTurn(threadId: string): void {
    this.ranTurn.add(threadId);
  }

  /** True once for each thread that ran a turn; a failed read is not retried. */
  claim(threadId: string): boolean {
    if (!this.ranTurn.has(threadId) || this.attempted.has(threadId)) return false;
    this.attempted.add(threadId);
    return true;
  }
}

/**
 * Step 11.1: Codex's own credit estimate for a root thread, read once as the thread ends (the session closes
 * gracefully, or its thread is replaced) and stored beside the trial arm. The reading is cumulative, so a later
 * row for the same thread supersedes an earlier one. It exists only while the app-server is alive: a forced
 * termination, an app-server that died, or a thread that never ran a turn here has no reading, and none is made up.
 */
export async function recordCodexThreadCredits(ledger: CodexThreadCreditsLedger, host: {
  client: CodexUsageReadClient | null;
  threadId: string | null;
  live: boolean;
  record: Pick<SessionThreadCreditsRecord, 'provider' | 'sessionKind' | 'instanceId' | 'arm' | 'armKey'>;
  publish(record: SessionThreadCreditsRecord): void;
}): Promise<void> {
  if (!host.live || !host.client || !host.threadId || !ledger.claim(host.threadId)) return;
  const credits = await readCodexThreadCredits(host.client, host.threadId);
  if (credits) host.publish({ event: 'thread-credits', ...host.record, ...credits });
}
